-- Contenido jugable (rondas / pares) para los 3 primeros motores de juego
-- construidos: arrastrar.php (Arrastrar y soltar) y memoria.php (Memoria).
-- Depende de que ya exista la tabla contenido_juego
-- (2026_08_26_crear_contenido_juego.sql) y los juegos de
-- 2026_08_26_juegos_grado1_lengua_castellana.sql.

INSERT INTO contenido_juego (id_actividad, datos_json)
SELECT a.id_actividad, x.datos_json
FROM (
    SELECT 'El Jardín de las Vocales' AS nombre, '{"rondas": [{"instruccion": "Arrastra la imagen que empieza con A", "zonas": [{"id": "flor", "etiqueta": "A", "emoji": "🌸"}], "piezas": [{"id": "A", "emoji": "🕷️", "etiqueta": "araña", "zona": "flor"}, {"id": "E", "emoji": "🐘", "etiqueta": "elefante", "zona": null}, {"id": "O", "emoji": "🐻", "etiqueta": "oso", "zona": null}]}, {"instruccion": "Arrastra la imagen que empieza con E", "zonas": [{"id": "flor", "etiqueta": "E", "emoji": "🌸"}], "piezas": [{"id": "E", "emoji": "🐘", "etiqueta": "elefante", "zona": "flor"}, {"id": "A", "emoji": "🕷️", "etiqueta": "araña", "zona": null}, {"id": "U", "emoji": "🍇", "etiqueta": "uva", "zona": null}]}, {"instruccion": "Arrastra la imagen que empieza con I", "zonas": [{"id": "flor", "etiqueta": "I", "emoji": "🌸"}], "piezas": [{"id": "I", "emoji": "🦎", "etiqueta": "iguana", "zona": "flor"}, {"id": "O", "emoji": "🐻", "etiqueta": "oso", "zona": null}, {"id": "E", "emoji": "🐘", "etiqueta": "elefante", "zona": null}]}, {"instruccion": "Arrastra la imagen que empieza con O", "zonas": [{"id": "flor", "etiqueta": "O", "emoji": "🌸"}], "piezas": [{"id": "O", "emoji": "🐻", "etiqueta": "oso", "zona": "flor"}, {"id": "U", "emoji": "🍇", "etiqueta": "uva", "zona": null}, {"id": "A", "emoji": "🕷️", "etiqueta": "araña", "zona": null}]}, {"instruccion": "Arrastra la imagen que empieza con U", "zonas": [{"id": "flor", "etiqueta": "U", "emoji": "🌸"}], "piezas": [{"id": "U", "emoji": "🍇", "etiqueta": "uva", "zona": "flor"}, {"id": "I", "emoji": "🦎", "etiqueta": "iguana", "zona": null}, {"id": "O", "emoji": "🐻", "etiqueta": "oso", "zona": null}]}]}' AS datos_json
    UNION ALL
    SELECT 'Constructor de Sílabas' AS nombre, '{"rondas": [{"instruccion": "Arma la sílaba ma", "zonas": [{"id": "cons", "etiqueta": "M", "emoji": "🧱"}], "piezas": [{"id": "A", "etiqueta": "A", "zona": "cons"}, {"id": "E", "etiqueta": "E", "zona": null}, {"id": "U", "etiqueta": "U", "zona": null}]}, {"instruccion": "Arma la sílaba mo", "zonas": [{"id": "cons", "etiqueta": "M", "emoji": "🧱"}], "piezas": [{"id": "O", "etiqueta": "O", "zona": "cons"}, {"id": "I", "etiqueta": "I", "zona": null}, {"id": "A", "etiqueta": "A", "zona": null}]}, {"instruccion": "Arma la sílaba pa", "zonas": [{"id": "cons", "etiqueta": "P", "emoji": "🧱"}], "piezas": [{"id": "A", "etiqueta": "A", "zona": "cons"}, {"id": "U", "etiqueta": "U", "zona": null}, {"id": "I", "etiqueta": "I", "zona": null}]}, {"instruccion": "Arma la sílaba pe", "zonas": [{"id": "cons", "etiqueta": "P", "emoji": "🧱"}], "piezas": [{"id": "E", "etiqueta": "E", "zona": "cons"}, {"id": "O", "etiqueta": "O", "zona": null}, {"id": "A", "etiqueta": "A", "zona": null}]}, {"instruccion": "Arma la sílaba la", "zonas": [{"id": "cons", "etiqueta": "L", "emoji": "🧱"}], "piezas": [{"id": "A", "etiqueta": "A", "zona": "cons"}, {"id": "I", "etiqueta": "I", "zona": null}, {"id": "U", "etiqueta": "U", "zona": null}]}, {"instruccion": "Arma la sílaba lu", "zonas": [{"id": "cons", "etiqueta": "L", "emoji": "🧱"}], "piezas": [{"id": "U", "etiqueta": "U", "zona": "cons"}, {"id": "A", "etiqueta": "A", "zona": null}, {"id": "E", "etiqueta": "E", "zona": null}]}]}' AS datos_json
    UNION ALL
    SELECT 'Memo-Vocales' AS nombre, '{"pares": [{"letra": "A", "imagen_emoji": "🕷️", "imagen_texto": "araña"}, {"letra": "E", "imagen_emoji": "🐘", "imagen_texto": "elefante"}, {"letra": "I", "imagen_emoji": "🦎", "imagen_texto": "iguana"}, {"letra": "O", "imagen_emoji": "🐻", "imagen_texto": "oso"}, {"letra": "U", "imagen_emoji": "🍇", "imagen_texto": "uva"}]}' AS datos_json
) x
JOIN actividades a ON a.nombre = x.nombre
ON DUPLICATE KEY UPDATE datos_json = VALUES(datos_json);
